// Package l10n holds MyGo's own strings, those of the controls of package
// ui, of the code editor and the diff viewer, and of the roles of menus,
// in the languages MyGo is translated to: a library's catalog (see
// i18n.NewLibraryCatalog) of the namespace mygo, whose functions say them
// in the language the app shows. An app changes them, or translates them
// to its other languages, with keys "mygo.<key>" in its own catalogs, as
// "mygo.cancel" in its de.json.
//
// en.json, the source, is always linked, as messages/en.json: its
// messages without their descriptions, which only `mygo generate` reads. The translations to the other
// languages (Languages) are packages of their own, in locales/<tag> at the
// root of the module, which an app imports for the languages it ships, as
// the code `mygo generate` writes for its catalogs does: an app does not
// carry the translations to languages it does not show. catalog_gen.go,
// languages_gen.go and the packages of the translations are generated by
// `go generate`, with the code generator of apps' catalogs
// (internal/i18ngen).
package l10n

import (
	"embed"
	"io/fs"
)

//go:generate go run gen.go

// Namespace is the namespace of the keys with which apps change MyGo's
// strings: "mygo.<key>".
const Namespace = "mygo"

// Add adds the translations of fsys, "<tag>.json", to MyGo's strings: the
// package of each translation adds its own as it is imported.
func Add(fsys fs.FS) {
	if err := Catalog.Add(fsys); err != nil {
		panic(err)
	}
}

// sources are the catalogs as they are written, with their descriptions.
//
//go:embed *.json
var sources embed.FS

// FS returns the catalogs as they are written, which `mygo generate`
// checks the keys "mygo.<key>" of apps against: only it links them.
func FS() fs.FS { return sources }
